<?php
declare(strict_types=1); requireRole('subject-officer'); require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../includes/activity.php';
$activePage='item-categories';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim((string)($_POST['name']??''));$type=(string)($_POST['distribution_type']??'');$returnable=isset($_POST['returnable'])?1:0;if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(mb_strlen($name)<2||mb_strlen($name)>120)$errors[]='Enter a valid category name.';if(!in_array($type,['direct','request-based'],true))$errors[]='Select a distribution type.';if(!$errors){try{$s=database()->prepare('INSERT INTO item_categories(name,distribution_type,returnable,created_by) VALUES(:name,:type,:returnable,:user)');$s->execute(['name'=>$name,'type'=>$type,'returnable'=>$returnable,'user'=>$_SESSION['user_id']]);$id=(int)database()->lastInsertId();logActivity('Item Categories','Created item category — '.$name,'CAT-'.$id);$_SESSION['flash_success']='Item category created.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=item-categories');exit;}catch(PDOException $e){error_log($e->getMessage());$errors[]=$e->getCode()==='23000'?'That category already exists.':'Unable to create category.';}}}
try{$rows=database()->query('SELECT c.*,(SELECT COUNT(*) FROM inventory_items i WHERE i.category_id=c.id) item_count FROM item_categories c ORDER BY c.name')->fetchAll();}catch(PDOException $e){$rows=[];$errors[]='Item categories are unavailable. Import database/migration_master_data.sql.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Item Categories | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/subject-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Item Categories</h1></div></header><main class="dashboard-content master-config-page"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="admin-data-card"><div class="admin-data-header"><h2>Create Item Category</h2></div><form method="post" class="master-inline-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><label>Category Name<input name="name" required maxlength="120"></label><label>Distribution Type<select name="distribution_type" required><option value="">Select type</option><option value="direct">Direct Distribution</option><option value="request-based">Request-Based Distribution</option></select></label><label class="master-checkbox"><input type="checkbox" name="returnable"> Returnable item category</label><button class="admin-primary-action">Create Category</button></form></section><section class="admin-data-card master-list-card"><div class="admin-data-header"><h2>Configured Categories</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table"><thead><tr><th>Category</th><th>Distribution Type</th><th>Returnable</th><th>Items</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="admin-empty-row">No item categories available.</td></tr><?php else:foreach($rows as $row):?><tr><td><strong><?=htmlspecialchars($row['name'],ENT_QUOTES,'UTF-8')?></strong></td><td><?=ucwords(str_replace('-',' ',$row['distribution_type']))?></td><td><?=$row['returnable']?'Yes':'No'?></td><td><?=(int)$row['item_count']?></td><td><?=ucfirst($row['status'])?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
